mapper.select:
SELECT gp.name as name, gp.person_num as personNum, gp.common_id as commonId, gd.price_ori as priceOri, gd.price as price, gc.common_image as commonImage, gc.common_name as commonName, gd.goods_id as goodsId FROM ${database.prefix.activity}hou_addon_activity_piecing_together gp LEFT JOIN ${database.prefix.activity}hou_addon_activity_piecing_together_detail gd ON gp.pintuan_id = gd.pintuan_id LEFT JOIN ${database.prefix.goods}hou_goods_common gc ON gp.common_id = gc.common_id WHERE 1 = 1
and gp.pintuan_id = #{pinTuanId}
group by gc.common_id

SELECT gb.goods_id, gb.common_id, gs.goods_stock, gb.goods_spec AS goods_spec_name, pd.price, pd.price_one, pd.price_ori, pd.detail_id FROM ${database.prefix.activity}hou_addon_activity_piecing_together_detail pd LEFT JOIN ${database.prefix.goods}hou_goods_base gb ON gb.goods_id = pd.goods_id LEFT JOIN ${database.prefix.goods}hou_goods_stock gs on gb.goods_id = gs.goods_id WHERE gb.goods_is_shelves = 1
and gb.common_id = #{commonId,jdbcType=INTEGER}
and pd.pintuan_id= #{pintuanId,jdbcType=INTEGER}

select pintuan_id, name, person_num, common_id, start_time, end_time, update_time, status from ${database.prefix.activity}hou_addon_activity_piecing_together where 1=1
and status = #{param.status,jdbcType=INTEGER}
and shop_id = #{param.shopId,jdbcType=INTEGER}
and name LIKE CONCAT('%',#{param.name },'%')
order by update_time desc

SELECT DISTINCT pm.mark_id, pm.detail_id, pm.created_time, pm.num, pm.user_name, pm.surplus_num, pm.user_avatar, pp.start_hour, pp.end_time FROM ${database.prefix.activity}hou_addon_activity_piecing_together_mark pm LEFT JOIN ${database.prefix.activity}hou_addon_activity_piecing_together_detail pd ON pm.detail_id = pd.detail_id LEFT JOIN ${database.prefix.activity}hou_addon_activity_piecing_together pp ON pp.pintuan_id = pd.pintuan_id LEFT JOIN ${database.prefix.activity}hou_addon_activity_piecing_together_temp pt ON pt.mark_id = pm.mark_id WHERE pm.STATUS = 0 AND ( now() BETWEEN pp.start_time AND pp.end_time ) AND date_add( pm.created_time, INTERVAL pp.start_hour HOUR ) > NOW() AND pt.pay_start = 1
and pp.common_id = #{param.commonId,jdbcType=INTEGER}
order by pm.created_time asc
